package dev.presidencia;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.item.*;import net.minecraft.entity.*;import net.minecraft.util.math.*;import net.minecraft.world.GameMode;
public class V031Tests implements FabricGameTest {
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void beerIntoxicatesAndReturnsBottle(TestContext c){var p=c.createMockPlayer(GameMode.SURVIVAL);var result=Terror.BEER.finishUsing(new ItemStack(Terror.BEER),c.getWorld(),p);c.assertTrue(p.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.NAUSEA),"Drinker gets nausea");c.assertEquals(p.getStatusEffect(net.minecraft.entity.effect.StatusEffects.NAUSEA).getDuration(),600,"Thirty seconds");c.assertTrue(result.isOf(Items.GLASS_BOTTLE),"Empty bottle returned");c.assertEquals(Terror.BEER.getMaxCount(),64,"Full stacks supported");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void alcoholRecipeIsVisibleAndRegistered(TestContext c){var entry=c.getWorld().getRecipeManager().get(Terror.id("alcool")).orElseThrow();c.assertFalse(entry.value().isIgnoredInRecipeBook(),"Recipe appears in recipe book");c.assertEquals(entry.value().getIngredients().size(),2,"Water bottle and cane shown");c.assertTrue(entry.value().getResult(c.getWorld().getRegistryManager()).isOf(Terror.ALCOHOL),"Recipe output alcohol");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void fullDirtArmorHalvesFallDamage(TestContext c){var full=Terror.LULA.create(c.getWorld());var bare=Terror.LULA.create(c.getWorld());var partial=Terror.LULA.create(c.getWorld());var items=new Item[]{DirtArmor.HELMET,DirtArmor.CHEST,DirtArmor.LEGS,DirtArmor.BOOTS};var slots=new EquipmentSlot[]{EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET};for(int i=0;i<4;i++)full.equipStack(slots[i],new ItemStack(items[i]));partial.equipStack(EquipmentSlot.HEAD,new ItemStack(DirtArmor.HELMET));full.damage(c.getWorld().getDamageSources().fall(),10);bare.damage(c.getWorld().getDamageSources().fall(),10);partial.damage(c.getWorld().getDamageSources().fall(),10);c.assertEquals(full.getHealth(),495f,"Full set halves fall");c.assertEquals(bare.getHealth(),490f,"Bare fall unchanged");c.assertEquals(partial.getHealth(),490f,"Partial set no reduction");c.assertTrue(DirtArmor.MATERIAL.value().toughness()>ArmorMaterials.NETHERITE.value().toughness(),"Tougher than netherite");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void lulaDropsTwoBeerStacks(TestContext c){var lula=Terror.LULA.create(c.getWorld());lula.setPosition(Vec3d.ofBottomCenter(c.getAbsolutePos(new BlockPos(2,2,2))));c.getWorld().spawnEntity(lula);lula.damage(c.getWorld().getDamageSources().genericKill(),10000);int beer=c.getWorld().getEntitiesByClass(net.minecraft.entity.ItemEntity.class,lula.getBoundingBox().expand(2),e->e.getStack().isOf(Terror.BEER)).stream().mapToInt(e->e.getStack().getCount()).sum();c.assertEquals(beer,128,"128 beers dropped");lula.discard();c.complete();}
}
